"""Freeze contracts once; never update thresholds after numerical fitting."""
from pathlib import Path
import json, hashlib, datetime
R = Path(__file__).resolve().parents[1]
stamp = datetime.datetime.now(datetime.timezone.utc).isoformat()
common = dict(round_tag='X1b-crown-loop', frozen_utc=stamp, parent='LANE_X1_CROWN_LOOP; PROOF_LANE_XREVIEW_RESTORATIVE', consumer='Prosthetics researcher: transferable crown experiment and falsifiable prediction', resources=dict(threads_max=4, intermediate_bytes_max=3000000000), review_state='PENDING_INDEPENDENT_REVIEW')
contracts = {'PORTABLE_GATES': dict(capability='Run from a copied package without the original dental checkout; reject wrong exports and mechanisms', obstacle='Absolute source imports and existence-only surface check; force agreement can hide wrong failure mechanism', changed_operation='Vendor exact local modules and selected arrays; recompute export vertices against source SDF; classify every specimen', metrics=dict(clean_copy_exit_code=0, raw_response_relative_error_max=0.05, export_sdf_p99_um_max=60, export_volume_roundtrip_relative_error_max=1e-05, force_log_RMSE_max=0.3, gap_bias_absolute_um_max=30, failure_mode_non_tensile_fraction_max=0.5, all_faults_must_reject=True), decision='PASS portability only if isolated copied run succeeds; mechanism FAIL if incompatible modes dominate (>50%) in any design-angle stratum; UNKNOWN if any mode/origin is unknown; any individual incompatible event prevents full mechanistic PASS and is retained. No clinical validity follows.', strongest_equally_informed_control='ProofLane corrected scorer; independent direct-triangle interpolation and STL/3MF volume comparison; scalar raw-response basis', falsifiers=['Perturbed exported crown passes surface check', 'Contact damage/debonding/die fracture majority passes mechanism', 'Unknown mode yields PASS', 'Raw force x1.5 or frozen hash mutation escapes'], full_cost=dict(preparation='Copy selected source arrays and modules with hashes; no source-tree cache', fit='none', discovery='review-guided repairs', validation='isolated clean copy, actual export perturbation and CSV faults', queries='all 45 saved FE fields/90 loadcases', fallback='preserve failed gates; no graph writes in run_all')), 'LITERATURE_R1': dict(capability='Prediction interval for a new zirconia crown study using material, thickness and observed setup', obstacle='Bar-to-crown scale and lab heterogeneity swamp discrimination', changed_operation='Extract primary group means/SD/n with table locators; REML study random intercept in log force; leave-one-study-out', equation='log(mean F_N)=beta_material + beta_t*log(t_mm) + beta_angle*angle/30 + beta_cement*I_resin + b_study + e; b~N(0,tau^2), Var(e)=log(1+(SD/mean)^2)/n + sigma^2', eligibility='Primary full-contour zirconia crown fracture groups with explicit material class, measured mean/SD/n and nominal restoration thickness. Exclude copings/discs/veneers/bridges/clinical rates, secondary repeated observations; missing field UNKNOWN. Supplemental already-local primary XML may be used with manifest. Preparation reduction is not restoration thickness.', features=['material_3Y_4Y_5Y', 'log_nominal_occlusal_thickness_mm', 'angle_div_30', 'resin_cement'], metrics=dict(min_independent_studies=5, study_balanced_LOSO_log_RMSE_max=0.3, interval_level=0.9, study_balanced_LOSO_coverage_min=0.8, prospective_interval_upper_lower_ratio_max=3.0, same_information_improvement_RMSE_fraction_min=0.1), decision='Predictive adequacy requires study count, RMSE, held-out coverage, feature estimability and interval width gates. Ordinary regression on the same rows is the strong control. No claimed win when improvement <10%. Unsupported material/setup or out-of-span target UNKNOWN even if a numeric diagnostic is emitted.', strongest_equally_informed_control='Study-balanced log-linear ordinary regression with identical features, measured group uncertainty and new-study residual prediction variance', falsifiers=['Held-out study logRMSE>.30', '90% band coverage<.80', 'Rank-deficient target prediction', 'Band upper/lower>3', 'Injected force x10 does not fail'], full_cost=dict(preparation='Read local 425-record LIT_CROWN plus selected existing XML; provenance and ten-row manual check', fit='REML beta/tau/sigma separately inside each fold', discovery='one fixed feature set; no tuning on held-out residuals', validation='all study-held-out folds; freeze fold predictions before scoring', queries='three 3Y export targets, angles 0/30 with domain flags', fallback='keep FAIL/UNKNOWN and pursue matched within-study ratio R2'))}
leaves = [('geometry', 'DERIVED_UNDER_ASSUMPTIONS', 'mesh vertex x samples trilinear phi(x); p99 |phi| in mm -> um', 'Grid and source SDF are saved X1 data, not anatomy truth; stop at numerical export consistency'), ('elasticity', 'CONSTITUTIVE_CLOSURE', 'sigma=C(E,nu):sym grad u; K u=f', 'Linear perfect tie; cement/contact fracture unmodeled, so mode/origin measurement is a necessary test'), ('fracture', 'CONSTITUTIVE_CLOSURE', 'F50=sigma0*(ln2/integral(max(sigma/F,0)^m)dA)^(1/m)', 'Saved stress tensors determine response, defect population is not measured in these crowns'), ('published_force', 'EXTERNALLY_MEASURED', 'Group mean/SD/n from primary table with DOI+table+row', 'Stop at published summaries; individual distributions and mechanism-specific loads remain unavailable'), ('study_effect', 'CONSTITUTIVE_CLOSURE', 'b_study normal with fitted variance tau^2', 'Summaries cannot separate lab, batch, cusp morphology and contact; REML is empirical predictive closure'), ('interval', 'DERIVED_UNDER_ASSUMPTIONS', 'log interval = prediction +/- t_quantile*sqrt(x Cov(beta) x + tau^2 + sigma^2 + target sampling variance)', 'Normal-log and independent-study assumptions; few studies require held-out scoring and provisional status'), ('failure_origin', 'UNKNOWN', 'fractography: tensile intaglio, contact, cement, die, unknown', 'No fabricated X1 specimen exists; force agreement alone cannot identify mechanism'), ('as_built_gap', 'UNKNOWN', 'MG_distance_observed - MG_distance_CAD', 'No matching scanner/mill batch; do not narrow inherited gap scenarios by borrowing heterogeneous means')]
for (tag, body) in contracts.items():
    p = R / f'PREREG_{tag}.json'
    if p.exists():
        raise SystemExit(f'Refuse overwriting {p.name}')
    p.write_text(json.dumps(common | body, indent=2) + '\n')
    p.with_suffix('.sha256').write_text(hashlib.sha256(p.read_bytes()).hexdigest() + '\n')
(R / 'DECOMPOSITION.json').write_text(json.dumps(dict(idea='Discriminating model-to-lab crown loop', mechanism='Separate numerical exports, tensile failure physics and study transfer', equations=[c['equation'] for c in contracts.values() if 'equation' in c], operation='raw response replay -> source surface gate -> primary extraction -> study held-out calibration -> frozen lab comparison', representation='SDF, stress tensors, study-group table, classified specimen CSV', leaves=[dict(name=n, status=s, relation=e, stopping_argument=a) for (n, s, e, a) in leaves]), indent=2) + '\n')
print('Frozen', list(contracts), stamp)
